INSERT INTO movies (title, description, poster_url, rating, duration_minutes, director, cast_list, release_date, status) VALUES ('Neon Frontier', 'In 2087, a rogue cartographer discovers a signal from beyond the known star maps, drawing her into a conspiracy that spans three civilizations.', 'https://picsum.photos/seed/movie1/500/750', 'PG-13', 138, 'Yuki Tanaka', 'Elena Vasquez, James Okafor, Petra Novak', '2026-01-10', 'now_showing');
INSERT INTO movies (title, description, poster_url, rating, duration_minutes, director, cast_list, release_date, status) VALUES ('Midnight Ledger', 'A forensic accountant uncovers a decade-old fraud that ties her own family to an unsolved disappearance.', 'https://picsum.photos/seed/movie2/500/750', 'R', 124, 'Marcus Cole', 'David Kim, Rosa Alvarez, Tom Reilly', '2026-02-11', 'now_showing');
INSERT INTO movies (title, description, poster_url, rating, duration_minutes, director, cast_list, release_date, status) VALUES ('Golden Hour', 'Two strangers keep meeting at the same San Francisco overlook every year on the same day, for reasons neither can explain.', 'https://picsum.photos/seed/movie3/500/750', 'PG-13', 109, 'Ingrid Solberg', 'Maya Lin, Owen Brooks, Claire Dupont', '2026-03-12', 'now_showing');
INSERT INTO movies (title, description, poster_url, rating, duration_minutes, director, cast_list, release_date, status) VALUES ('Steel Horizon', 'An engineer must stop a runaway orbital elevator before it tears through the equator.', 'https://picsum.photos/seed/movie4/500/750', 'PG-13', 131, 'Derek Osei', 'Marcus Reed, Tanya Brooks, Victor Hale', '2026-04-13', 'now_showing');
INSERT INTO movies (title, description, poster_url, rating, duration_minutes, director, cast_list, release_date, status) VALUES ('The Quiet Orchard', 'A grieving beekeeper rebuilds her late fathers orchard and, with it, her relationship with her estranged brother.', 'https://picsum.photos/seed/movie5/500/750', 'PG', 101, 'Helene Fischer', 'Anna Voss, Peter Lund, Ingrid Hahn', '2026-05-14', 'now_showing');
INSERT INTO movies (title, description, poster_url, rating, duration_minutes, director, cast_list, release_date, status) VALUES ('Comedy of Errors Inc.', 'A startups worst product launch becomes the best thing that ever happened to its founders.', 'https://picsum.photos/seed/movie6/500/750', 'PG-13', 97, 'Jamal Whitfield', 'Sam Ortiz, Debra Chan, Kyle Nolan', '2026-06-15', 'now_showing');
INSERT INTO movies (title, description, poster_url, rating, duration_minutes, director, cast_list, release_date, status) VALUES ('Hollow Point', 'A retired sniper is pulled back for one last job that was never really about the target.', 'https://picsum.photos/seed/movie7/500/750', 'R', 116, 'Renee Aubert', 'Frank Castillo, Nadia Petrov, Ben Wu', '2026-01-16', 'now_showing');
INSERT INTO movies (title, description, poster_url, rating, duration_minutes, director, cast_list, release_date, status) VALUES ('Whispers in Attic 7', 'A family renovating an old apartment building keeps finding rooms that were never on the blueprints.', 'https://picsum.photos/seed/movie8/500/750', 'R', 98, 'Colin Ashworth', 'Zoe Marlowe, Grant Ellis, Ivy Chen', '2026-02-17', 'now_showing');
INSERT INTO movies (title, description, poster_url, rating, duration_minutes, director, cast_list, release_date, status) VALUES ('Paper Constellations', 'An origami-folding girl discovers her paper creatures come alive on the night of a lunar eclipse.', 'https://picsum.photos/seed/movie9/500/750', 'PG', 94, 'Mio Sakata', 'Voices of Aiko Sato, Leo Marchetti', '2026-03-18', 'now_showing');
INSERT INTO movies (title, description, poster_url, rating, duration_minutes, director, cast_list, release_date, status) VALUES ('Last Exit East', 'Three siblings drive across the country to sell their late mothers diner before the bank forecloses.', 'https://picsum.photos/seed/movie10/500/750', 'PG-13', 122, 'Omar Siddiqui', 'Farah Idris, Noah Kessler, Wendy Zhou', '2026-04-19', 'now_showing');
