-- BOOKING SEATS (linking sample seats to bookings)

-- Sync available_seats after bookings
UPDATE showtimes st SET available_seats = available_seats - (
  SELECT COUNT(*) FROM booking_seats bs
  JOIN bookings bk ON bs.booking_id = bk.id
  WHERE bk.showtime_id = st.id AND bk.booking_status = 'confirmed'
);
